use android_tools::{
    generated_artifacts::{ModelConsumerVersion, parse_generated_artifacts},
    import_facts::{ImportFactsBinding, parse_import_facts},
    project_model::{VariantId, parse_model},
};
use anyhow::{Context as _, Result, ensure};
use std::{env, fs, path::PathBuf};
fn main() -> Result<()> {
    let mut args = env::args().skip(1);
    let root = PathBuf::from(args.next().context("actual private project root")?).canonicalize()?;
    let output = fs::read_to_string(args.next().context("complete Gradle capture log")?)?;
    let scenario = args.next().context("baseline, nested, late")?;
    let model = parse_model(&output, &root)?;
    let binding = ImportFactsBinding {
        model_revision: 1,
        selection_revision: 1,
        selected_variants: vec![VariantId { module: ":mobile".into(), variant: "demoDebug".into() }],
    };
    let snapshot = parse_import_facts(&output, &model, binding.clone())?;
    snapshot.ensure_current(&model, &binding)?;
    let consumer = ModelConsumerVersion {
        major: 66, minor: 1, description: Some("supplementary official identity capture".into()),
    };
    let v2 = parse_generated_artifacts(&output, &model, 1, &consumer)?;
    v2.ensure_current(&model, 1)?;
    let observed = |value: &serde_json::Value, key: &str| -> Result<serde_json::Value> {
        let member = &value[key];
        ensure!(member["result"]["status"] == "available", "{key}: {member}");
        Ok(member["result"]["value"].clone())
    };
    let catalogue = serde_json::to_value(snapshot.projects()?)?;
    let projects = catalogue.as_array().context("ordered project catalogue")?;
    ensure!(projects.len() > model.modules.len(), "root holders are retained");
    let by_path = |path: &str| -> Result<&serde_json::Value> {
        projects.iter().find(|p| p["projectPath"]["result"]["value"] == path)
            .with_context(|| format!("captured official project {path}"))
    };
    let root_project = by_path(":")?;
    let root_name = observed(root_project, "projectName")?;
    ensure!(root_name.as_str() != root.file_name().and_then(|v| v.to_str()), "root declared name differs from folder");
    ensure!(observed(root_project, "parentProjectPath")?.is_null(), "root has nullable parent");
    ensure!(observed(root_project, "ideaPluginPresent")? == false);
    ensure!(observed(root_project, "ideaModuleName")?.is_null(), "no Idea plugin yields observed nullable name");
    for project in projects {
        let path = observed(project, "projectPath")?;
        ensure!(observed(project, "buildTreePath")? == path, "official public build-tree identity");
        ensure!(observed(project, "referenceIdentityPath")? == path, "independent internal reference identity");
        ensure!(observed(project, "rootName")? == root_name);
        ensure!(observed(project, "rootDirectory")?.as_str() == root.to_str());
    }
    let mut oracle = serde_json::Value::Null;
    if scenario != "baseline" {
        for (path, directory) in [(":left:shared", "jvm-one"), (":right:shared", "jvm-two")] {
            let project = by_path(path)?;
            ensure!(observed(project, "projectName")? == "shared", "duplicate raw leaf names preserved");
            ensure!(observed(project, "projectDirectory")?.as_str() == root.join(directory).to_str());
            ensure!(observed(project, "ideaPluginPresent")? == true);
            ensure!(observed(project, "parentProjectPath")? == path.rsplit_once(':').context("nested parent")?.0);
            snapshot.project(path)?;
        }
        ensure!(observed(by_path(":left")?, "parentProjectPath")? == ":");
        ensure!(observed(by_path(":right")?, "parentProjectPath")? == ":");
        ensure!(observed(by_path(":right:shared")?, "ideaModuleName")? == "shared-collision");
        if scenario == "late" {
            let records: Vec<_> = output.lines().filter_map(|line| line.strip_prefix("KODA_IDENTITY_ORACLE=")).collect();
            ensure!(records.len() == 1, "exactly one independent official Idea-name oracle");
            oracle = serde_json::from_str(records[0])?;
            ensure!(oracle["module"] == ":left:shared");
            ensure!(oracle["ideaModuleName"] == "configured-after-project-evaluation");
            ensure!(observed(by_path(":left:shared")?, "ideaModuleName")? == oracle["ideaModuleName"], "capture after every project evaluation callback");
        } else {
            ensure!(scenario == "nested");
            ensure!(observed(by_path(":left:shared")?, "ideaModuleName")? == "shared-collision");
        }
    }
    println!("{}", serde_json::to_string_pretty(&serde_json::json!({
        "supplementaryOnly": true, "originalReferenceTestCredit": 0,
        "scenario": scenario, "root": root, "actualGradleVersion": snapshot.gradle_version(),
        "callerModelRevision": binding.model_revision, "callerSelectionRevision": binding.selection_revision,
        "callerSelectedVariants": [{"module": ":mobile", "variant": "demoDebug"}],
        "basicCompiledModules": model.modules.len(), "rawProjectCatalogueCount": projects.len(),
        "orderedRawProjectCatalogue": catalogue, "buildIdentity": snapshot.build_identity(),
        "independentLateIdeaOracle": oracle, "basicAndV2AndImportFactsDecoded": true,
        "freshnessBindingVerified": true
    }))?);
    Ok(())
}
